</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

long long v;
vector<long long> sequence(17);

int solve(int index, long long value) {
    value = abs(value);
    if (index == 0) {
        return static_cast<int>(value);
    }
    int base = static_cast<int>(value / sequence[index]);
    int next_base = base + 1;
    int cost_option1 = base * (index + 1) + solve(index - 1, value - base * sequence[index]);
    int cost_option2 = next_base * (index + 1) + solve(index - 1, value - next_base * sequence[index]);
    return min(cost_option1, cost_option2);
}

int main() {
    scanf("%lld", &v);
    sequence[0] = 1;
    for (int i = 1; i < 17; ++i) {
        sequence[i] = sequence[i - 1] * 10 + 1;
    }
    printf("%d\n", solve(16, v));
    return 0;
}
